import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  optimizeDeps: {
    exclude: ['lucide-react'],
  },
  resolve: {
    // @aidxn/chrome is VENDORED, not installed — src/chrome/ is generated by
    // `npm run sync` in the aidxn-chrome repo and `npm run chrome:check`
    // fails the build if anyone hand-edits a copy.
    //
    // It is not a dependency because it cannot be one yet: a `file:` path
    // resolves on Aiden's machine and nowhere else (Netlify clones only this
    // repo), and a `git+https://` install needs aidxn-chrome to be public or
    // a GitHub token on every consumer's Netlify project. Importing through
    // the alias rather than a relative path means swapping to a real
    // published package later is this config change and nothing else — no
    // import in src/ has to move.
    alias: [
      { find: /^@aidxn\/chrome$/, replacement: path.resolve(root, 'src/chrome/index.ts') },
      { find: /^@aidxn\/chrome\//, replacement: path.resolve(root, 'src/chrome') + '/' },
    ],
  },
});
